const { existsSync } = await import('node:fs');
const input = process.env.PDF_PATH;
if (!input) throw new Error('Missing PDF_PATH');
if (!existsSync(input)) throw new Error('Input PDF not found');
globalThis.pdfPath = input;
globalThis.outPath = input.replace(/\.pdf$/i, '_placeholder.pdf');

const { PDFDocument } = await import('pdf-lib');
const { pdflibAddPlaceholder } = await import('@signpdf/placeholder-pdf-lib');
const { promises: fsPromises } = await import('node:fs');
const data = await fsPromises.readFile(globalThis.pdfPath);
const pdfDoc = await PDFDocument.load(data);
await pdflibAddPlaceholder({ pdfDoc });
const newPdfBytes = await pdfDoc.save();
await fsPromises.writeFile(globalThis.outPath, newPdfBytes);
